from common import *
dom('mongodb')
M('b','k',"How does MongoDB store data?","As BSON documents in collections","As rows in tables","As key-only values","As graph edges","Documents are JSON-like BSON objects grouped in collections.")
M('b','k',"Which method inserts a single document?","insertOne","addOne","put","append","db.users.insertOne({...}) adds one document.")
M('b','k',"Which method retrieves documents from a collection?","find","select","get","query","find accepts a filter and returns a cursor.")
M('i','k',"Which operator matches values greater than a given value?","$gt","$greater","$more","$above","$gt, $gte, $lt and $lte are the comparison operators.")
M('i','k',"Which method updates the first document that matches a filter?","updateOne","changeOne","modify","setOne","updateOne(filter, update) changes a single document.")
M('i','k',"Which operator sets a field to a new value in an update?","$set","$put","$assign","$change","$set changes or adds the named field.")
M('i','k',"What is the _id field?","A unique identifier indexed by default","An optional description","The collection name","A version number","Every document has a unique _id.")
M('i','k',"Which aggregation stage filters documents?","$match","$group","$sort","$project","$match works like a query filter inside a pipeline.")
M('i','k',"Which command creates an ascending index on email?","db.users.createIndex({ email: 1 })","db.users.index('email')","db.users.addIndex(email)","db.createIndex(users)","Index keys use 1 for ascending and -1 for descending.")
M('i','k',"How do you sort results by age in descending order?",".sort({ age: -1 })",".sort({ age: 'desc' })",".order({ age: -1 })",".sort({ age: 0 })","A value of -1 means descending.")
M('a','k',"What is sharding?","Distributing data across multiple servers","Backing up data","Encrypting data","Compressing data","Sharding scales horizontally using a shard key.")
M('a','k',"What is a replica set?","A group of mongod instances holding the same data for redundancy","A set of indexes","A copy of a collection","A shard key","One primary accepts writes and secondaries replicate it.")
M('a','k',"Which aggregation stage groups documents by a key and computes totals?","$group","$unwind","$limit","$skip","$group uses accumulators like $sum and $avg.")
M('a','k',"Which stage outputs one document per element of an array field?","$unwind","$lookup","$split","$expand","$unwind deconstructs arrays.")
M('a','k',"What does $lookup do?","Performs a left outer join with another collection","Runs text search","Sorts documents","Forces an index","$lookup joins documents from a second collection.")
S('i','k',"Which are valid BSON/MongoDB data types?",["String","ObjectId","Date"],["Table"],"MongoDB has no table type.")
S('a','k',"Which are logical query operators?",["$and","$or","$nor"],["$sum"],"$sum is an aggregation accumulator.")
T('b',"MongoDB requires every document in a collection to have the same fields.",False,"Collections are schema-flexible.")
T('i',"A MongoDB collection can store documents with different structures.",True,"Documents in one collection may differ.")
T('a',"MongoDB supports multi-document transactions on replica sets.",True,"Transactions are available on replica sets and sharded clusters.")
M('i','o',"If 3 of 5 users have age >= 18, what does this return?\ndb.users.countDocuments({ age: { $gte: 18 } })","3","5","2","0","countDocuments counts only matching documents.")
M('a','o',"With documents where n is 1, 2 and 3, what does this return?\ndb.c.aggregate([{ $group: { _id: null, t: { $sum: '$n' } } }])","{ _id: null, t: 6 }","{ t: 3 }","6","An error","Grouping with _id null sums every document.")
M('i','d',"db.users.find({ name: 'A' }).update(...) fails. What is the correct approach?","Use updateOne or updateMany with a filter and update document","Use drop","Use insert","Use rename","Cursors have no update method; use collection update methods.")
M('a','d',"A query on a collection with 10 million documents is slow. What is the first sensible step?","Run explain() and add a suitable index","Add more fields","Remove _id","Restart the server","explain shows whether the query scans the whole collection.")
M('a','s',"Orders contain items that are always read together with the order. What is the best design?","Embed the items inside the order document","Store each item in a separate collection and join every time","Store items as one long string","Create one collection per item","Embedding avoids joins when data is accessed together.")
M('i','s',"You need a unique email for every user. What should you do?","Create a unique index on email","Check emails in the browser","Use the _id field as email text","Use sharding","A unique index makes MongoDB reject duplicates.")
dom('expressjs')
M('b','k',"What is Express.js?","A minimal web framework for Node.js","A database","A front-end framework","A CSS tool","Express builds on Node's http module.")
M('b','k',"Which method creates an Express application?","express()","new Express()","createApp()","app.create()","const app = express() creates the app.")
M('b','k',"Which method starts the server listening on a port?","app.listen(3000)","app.start(3000)","app.run(3000)","app.open(3000)","listen binds the server to a port.")
M('b','k',"Which method defines a route for HTTP GET requests?","app.get(path, handler)","app.fetch(path)","app.read(path)","app.route.get()","Each HTTP verb has a matching method.")
M('i','k',"What are the arguments of a typical Express middleware function?","(req, res, next)","(request)","(res, req)","(error only)","next() passes control to the next middleware.")
M('i','k',"Which built-in middleware parses JSON request bodies?","express.json()","express.body()","express.parse()","bodyJson()","Add app.use(express.json()) before your routes.")
M('i','k',"How do you read a route parameter from /users/:id?","req.params.id","req.query.id","req.body.id","req.id","Route parameters are in req.params.")
M('i','k',"How do you read ?page=2 from the URL?","req.query.page","req.params.page","req.body.page","req.url.page","Query string values are in req.query.")
M('i','k',"Which method sends a JSON response?","res.json(obj)","res.sendJSON(obj)","res.write.json(obj)","res.object(obj)","res.json sets the content type and serialises the object.")
M('i','k',"How do you set an HTTP status code of 404 before sending?","res.status(404).send('Not found')","res.code(404)","res.set(404)","res.error(404)","status() is chainable with send or json.")
M('a','k',"Where must an error-handling middleware be placed?","After all routes and other middleware","Before express.json()","Only inside a route","Anywhere, order does not matter","Express matches middleware in the order it is registered.")
M('a','k',"What signature identifies an error-handling middleware?","(err, req, res, next)","(req, res)","(next, err)","(error)","Four arguments tell Express it handles errors.")
M('a','k',"What does express.Router() provide?","Modular, mountable route handlers","A database connection","A template engine","A session store","Routers group routes and mount at a path.")
M('i','k',"Which package helps allow cross-origin browser requests?","cors","helmet","morgan","dotenv","The cors middleware sets the CORS headers.")
M('a','k',"What does the helmet package do?","Sets security-related HTTP headers","Compresses responses","Logs requests","Parses cookies","helmet adds headers such as X-Content-Type-Options.")
S('i','k',"Which are valid Express response methods?",["res.send()","res.json()","res.redirect()"],["res.render404()"],"render404 does not exist.")
S('a','k',"Which are common uses of middleware?",["Logging requests","Authentication checks","Parsing request bodies"],["Compiling TypeScript at runtime for every request"],"Middleware handles cross-cutting request concerns.")
T('b',"Express can only serve JSON responses.",False,"It can send HTML, files, text and more.")
T('i',"If a middleware neither responds nor calls next(), the request hangs.",True,"The client waits until timeout.")
T('a',"Calling next(err) skips normal middleware and goes to error handlers.",True,"Express routes the error to the next error-handling middleware.")
M('i','o',"What does GET /hello return?\napp.get('/hello', (req, res) => res.send('Hi'));","Hi","404 Not Found","Cannot GET /hello","An empty string","The handler sends the text Hi.")
M('a','o',"What is the order of output when GET / is called?\napp.use((q,r,n)=>{console.log('A');n();});\napp.get('/',(q,r)=>{console.log('B');r.send('ok');});","A then B","B then A","Only B","Only A","Middleware registered first runs first.")
M('i','d',"req.body is undefined for a JSON POST request. What is the most likely fix?","Add app.use(express.json()) before the routes","Use res.body","Change POST to GET","Install Sass","Without a parser Express does not populate req.body.")
M('a','d',"Why does this crash with ERR_HTTP_HEADERS_SENT?\nres.send('a'); res.send('b');","A response can only be sent once per request","res.send is deprecated","The status code is missing","The port is busy","Sending headers twice is an error; return after responding.")
M('a','s',"You want every route under /api/v1 to require a valid token. What is the cleanest approach?","Mount a router at /api/v1 with an auth middleware applied to it","Copy the token check into every handler","Check tokens only in the browser","Disable the routes","Applying middleware at the router level avoids repetition.")
