M('b','k',"What is Node.js?","A JavaScript runtime built on the V8 engine","A front-end framework","A database","A CSS compiler","Node runs JavaScript outside the browser.")
M('b','k',"Which command installs a package from npm?","npm install <package>","node get <package>","npm fetch <package>","install npm <package>","npm install downloads and adds the package.")
M('b','k',"Which file lists a project's dependencies and scripts?","package.json","node.config","modules.txt","npm.lock only","package.json is the project manifest.")
M('i','k',"Which module reads and writes files?","fs","http","path","os","fs provides the file system API.")
M('i','k',"How do you import a module in CommonJS?","const fs = require('fs')","import fs from 'fs' only","include fs","using fs","require loads CommonJS modules.")
M('i','k',"What does the event loop do?","Processes callbacks and async work without blocking the main thread","Runs multiple JavaScript threads at once","Compiles code","Manages memory only","It lets Node handle many connections with one thread.")
M('i','k',"Which module is used to create an HTTP server without a framework?","http","net-http","server","web","http.createServer starts a basic server.")
M('i','k',"What is process.env used for?","Reading environment variables","Listing running processes","Opening files","Managing threads","Use it for configuration such as ports and keys.")
