M('a','k',"Why is fs.readFileSync problematic in a server handling many requests?","It blocks the event loop","It uses too little memory","It cannot read text","It requires a callback","Synchronous calls stop all other requests meanwhile.")
M('a','k',"Which Node feature lets you use multiple CPU cores?","The cluster module or worker_threads","setTimeout","process.nextTick","require.cache","cluster forks processes; worker_threads runs threads.")
M('a','k',"What is a Stream in Node.js?","An abstraction for processing data in chunks","A database cursor","A type of Promise","A DOM event","Streams avoid loading whole files into memory.")
M('i','k',"Which keyword is used with Promises to write asynchronous code that reads like synchronous code?","await (inside an async function)","yield","wait","pause","await pauses the async function until the promise settles.")
M('a','k',"What does module.exports do?","Defines what a module makes available to other files","Imports a module","Deletes a module","Lists installed modules","require returns the exported value.")
S('i','k',"Which are core Node.js modules?",["fs","path","http"],["express"],"express is a third-party package.")
