M('a','o',"What is the output order?\nPromise.resolve().then(()=>console.log('P')); process.nextTick(()=>console.log('T'));","T then P","P then T","Only P","Only T","nextTick runs before promise microtasks.")
M('i','d',"require('./util') fails with MODULE_NOT_FOUND although util.js exists. What is a likely cause?","The path or file name is wrong relative to the current file","Node is too old","npm is not installed","The file is empty","Relative paths resolve from the requiring file.")
M('a','s',"A Node API becomes slow when one endpoint does heavy CPU work. What is the best fix?","Move the work to worker_threads or a separate job queue","Add more setTimeout calls","Use synchronous fs","Restart each request","Offloading keeps the event loop free.")
CODE('b',"Sort numbers","Sort a list of integers in ascending order.","The first line has n. The second line has n space-separated integers.","Print the sorted numbers separated by single spaces.","1 <= n <= 1000",'javascript',
 ["5\n5 3 8 1 2","3\n10 -1 7","1\n42","6\n9 9 1 1 5 5","4\n-3 -10 0 2"],lambda s:' '.join(map(str,sorted(map(int,s.split('\n')[1].split())))),3,"Use Array.sort with a numeric comparator because the default sort is lexicographic.")
CODE('i',"Character frequency","Count how many times each letter appears in a lowercase word.","One line with a lowercase word (letters a-z).","Print each distinct letter with its count as letter:count, in alphabetical order, separated by spaces.","1 <= length <= 1000",'javascript',
 ["banana","aab","zzz","hello","abc"],lambda s:' '.join('%s:%d'%(c,s.strip().count(c)) for c in sorted(set(s.strip()))),5,"Count with an object or Map, then sort the keys alphabetically.")
