M('i','k',"Which syntax gives two-way binding with a form field?","[(ngModel)]=\"name\"","(ngModel)=\"name\"","[ngModel]=name","{{ngModel}}","Banana-in-a-box combines property and event binding.")
M('i','k',"What is a service in Angular used for?","Sharing logic and data across components","Styling a component","Defining routes only","Compiling TypeScript","Services are injected through dependency injection.")
M('i','k',"Which decorator makes a class available for dependency injection?","@Injectable","@Input","@Output","@ViewChild","@Injectable marks a class as a provider.")
M('i','k',"Which decorator receives data from a parent component?","@Input","@Output","@Injectable","@HostListener","@Input binds a property to a parent value.")
M('i','k',"Which class lets a child component emit custom events to its parent?","EventEmitter","Observable only","Subject only","Promise","@Output() works with EventEmitter.")
M('i','k',"Which directive repeats an element for each item in a list (classic syntax)?","*ngFor","*ngIf","ngSwitch","ngClass","ngFor loops over an iterable.")
