S('a','k',"Which are valid ways to share data between components?",["@Input from parent to child","@Output events from child to parent","A shared service"],["Direct DOM manipulation of another component"],"Use Angular's data flow rather than touching other components' DOM.")
T('b',"Angular applications are written mainly in TypeScript.",True,"TypeScript is the default language.")
T('i',"ngOnInit runs before the constructor.",False,"The constructor runs first, then ngOnInit.")
T('a',"Lazy loading lets Angular load feature modules only when they are needed.",True,"It reduces the initial bundle size.")
